script:
(function () {
  'use strict';
  // Buy vs lease: net cost of each option over the lease term, the same period for both.
  // Buying with a loan
  //   Sales tax = price x tax rate. Loan = price - down (+ tax and fees when financed; a down
  //   payment that covers everything means a cash purchase). Loan payments at the end of each month.
  //   Net cost = cash at purchase + loan payments made + loan balance paid off at the end
  //              - resale value, where resale = price x (1 - yearly depreciation)^(months / 12).
  // Leasing (closed-end, standard US method)
  //   Adjusted cap cost A = price - cash down (cap cost reduction). Residual R = residual % x price.
  //   Base payment = (A - R) / n + (A + R) x money factor, money factor = APR / 2400; the payment is
  //   taxed at the sales tax rate, as is the cash down. Payments at the start of each month.
  //   Net cost = cash down + its tax + upfront fees + payments + end-of-lease charges
  //              (the security deposit is paid and refunded, so it only adds opportunity cost).
  // Opportunity cost: each payment is grown to the end of the period at the investment return
  //   (compounded monthly); opportunity cost = that future value - the payments themselves.
  // Verified in Node (scratchpad tests/b3auto): cash purchase of $30,000 with 20%/yr depreciation over
  //   36 months nets $14,640 (30,000 - 30,000 x 0.8^3) vs a 50%-residual, 0% lease at $15,000; with a
  //   6% return the opportunity costs match the closed forms 30,000((1.005)^36 - 1) and the
  //   annuity-due future value of the lease payments; lease payment for $50,000, 48% residual,
  //   $10,000 down, money factor 0.00208, 36 months, 7% tax = $617.99 (same as our lease calculator's
  //   hand check); financed buy net cost = interest + depreciation + tax + fees; no NaN on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  // Cash flows: [{ m: month (0 = signing), amount }]. Returns the nominal total and its value at month T.
  function grow(flows, j, T) {
    var nominal = 0, fv = 0;
    flows.forEach(function (f) { nominal += f.amount; fv += f.amount * Math.pow(1 + j, T - f.m); });
    return { nominal: nominal, fv: fv };
  }

  function buy(o) {
    var tax = o.price * o.taxRate, total = o.price + tax + o.buyFees;
    var loan = o.price - o.down + (o.finance ? tax + o.buyFees : 0);
    var upfront = o.down + (o.finance ? 0 : tax + o.buyFees);
    if (loan <= 0.005 || upfront >= total) { loan = 0; upfront = total; }
    var pay = monthlyPayment(loan, o.loanRate, o.loanTerm), i = o.loanRate / 12, bal = loan, flows = [{ m: 0, amount: upfront }];
    var paid = 0;
    for (var m = 1; m <= Math.min(o.T, o.loanTerm) && bal > 0.005; m++) {
      var p = Math.min(pay, bal * (1 + i));
      bal = bal * (1 + i) - p;
      if (bal < 0.005) bal = 0;
      paid += p;
      flows.push({ m: m, amount: p });
    }
    if (bal > 0) flows.push({ m: o.T, amount: bal });
    var resale = o.price * Math.pow(1 - o.dep, o.T / 12);
    var g = grow(flows, o.j, o.T);
    var net = g.nominal - resale;
    return { tax: tax, loan: loan, payment: pay, upfront: upfront, paid: paid, payoff: bal, resale: resale,
             net: net, opportunity: g.fv - g.nominal, total: net + g.fv - g.nominal };
  }

  function lease(o) {
    var cap = o.price - o.leaseDown, residual = o.price * o.residualPct, mf = o.leaseApr / 2400;
    var base = (cap - residual) / o.T + (cap + residual) * mf;
    var payment = base * (1 + o.taxRate);
    var upfront = o.leaseDown * (1 + o.taxRate) + o.leaseFees + o.deposit;
    var flows = [{ m: 0, amount: upfront }];
    for (var m = 0; m < o.T; m++) flows.push({ m: m, amount: payment });
    flows.push({ m: o.T, amount: o.endFees });
    var g = grow(flows, o.j, o.T);
    var net = g.nominal - o.deposit;
    return { cap: cap, residual: residual, payment: payment, upfront: upfront, paid: payment * o.T,
             net: net, opportunity: g.fv - g.nominal, total: net + g.fv - g.nominal };
  }

  function setText(id, text) { el(id).textContent = text; }

  function signed(v) { return (v < 0 ? '−' : '') + money.format(Math.abs(v)); }

  function clearResults() {
    ['blVerdict', 'blBuyTotal', 'blLeaseTotal', 'blBuyPayment', 'blLeasePayment'].forEach(function (id) { setText(id, '–'); });
    setText('blVerdictLabel', 'Cheaper option');
    el('blBreakdown').innerHTML = '';
    el('blCash').hidden = true;
  }

  function update() {
    var o = {
      price: read('blPrice'), taxRate: read('blTaxRate', true), down: read('blDown', true),
      loanRate: read('blLoanRate'), loanTerm: read('blLoanTerm'), buyFees: read('blBuyFees', true),
      dep: read('blDep', true), finance: el('blFinance').checked, T: read('blLeaseTerm'),
      residualPct: read('blResidual'), leaseApr: read('blLeaseApr'), leaseDown: read('blLeaseDown', true),
      leaseFees: read('blLeaseFees', true), deposit: read('blDeposit', true), endFees: read('blEndFees', true),
      invest: read('blInvest', true)
    };
    var error = el('blError'), msg = '';
    if (isNaN(o.price) || o.price <= 0) msg = 'Enter a vehicle price greater than $0.';
    else if (isNaN(o.T) || o.T < 12 || o.T > 60 || o.T % 1 !== 0) msg = 'Enter a lease term of 12 to 60 whole months.';
    else if (isNaN(o.loanRate) || o.loanRate < 0 || o.loanRate > 40) msg = 'Enter a loan interest rate from 0% to 40%.';
    else if (isNaN(o.loanTerm) || o.loanTerm < 1 || o.loanTerm > 96 || o.loanTerm % 1 !== 0) msg = 'Enter a loan term of 1 to 96 whole months.';
    else if (isNaN(o.leaseApr) || o.leaseApr < 0 || o.leaseApr > 40) msg = 'Enter a lease interest rate from 0% to 40%.';
    else if (isNaN(o.residualPct) || o.residualPct <= 0 || o.residualPct >= 100) msg = 'Enter a residual value between 0% and 100% of the price.';
    else if (['taxRate', 'down', 'buyFees', 'dep', 'leaseDown', 'leaseFees', 'deposit', 'endFees', 'invest'].some(function (k) { return isNaN(o[k]) || o[k] < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (o.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (o.dep >= 100) msg = 'Enter a yearly depreciation below 100%.';
    else if (o.invest > 30) msg = 'Enter an investment return of 30% or less.';
    else if (o.price - o.leaseDown <= o.price * o.residualPct / 100) msg = 'The lease cash down is so large that it brings the cost below the residual value. Lower it.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }
    error.hidden = true;
    error.textContent = '';

    o.taxRate /= 100; o.loanRate /= 100; o.dep /= 100; o.residualPct /= 100; o.j = o.invest / 1200;
    var b = buy(o), l = lease(o), diff = b.total - l.total;
    if (Math.abs(diff) < 0.5) {
      setText('blVerdictLabel', 'Cheaper option');
      setText('blVerdict', 'About the same');
    } else {
      setText('blVerdictLabel', diff > 0 ? 'Leasing saves you' : 'Buying saves you');
      setText('blVerdict', money.format(Math.abs(diff)));
    }
    setText('blBuyTotal', money.format(b.total));
    setText('blLeaseTotal', money.format(l.total));
    setText('blBuyPayment', money.format(b.payment));
    setText('blLeasePayment', money.format(l.payment));
    el('blCash').hidden = b.loan > 0;

    var rows = [
      ['Cash at the start', b.upfront, l.upfront],
      ['Monthly payment', b.payment, l.payment],
      ['Payments during the ' + o.T + ' months', b.paid, l.paid],
      ['Loan balance paid off at the end', b.payoff, null],
      ['End-of-lease charges', null, o.endFees],
      ['Resale value you keep', -b.resale, null],
      ['Security deposit returned', null, -o.deposit],
      ['Net cost', b.net, l.net],
      ['Lost investment earnings', b.opportunity, l.opportunity],
      ['Total cost incl. lost earnings', b.total, l.total]
    ];
    el('blBreakdown').innerHTML = rows.map(function (r, idx) {
      var strong = idx >= rows.length - 1 ? ' class="font-semibold"' : '';
      return '<tr' + strong + '><th scope="row">' + r[0] + '</th><td>' + (r[1] === null ? '—' : signed(r[1])) +
        '</td><td>' + (r[2] === null ? '—' : signed(r[2])) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('blForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
